                .collect(),
            Value::Array(a) => a
                .iter()
                .map(|v| (v.as_str().map_or_else(|| v.to_string(), str::to_string), None))
                .collect(),
            _ => Vec::new(),
        },
        QKind::Score => match &q.criteria {
