pub fn from_url(url: &str) -> Self {
    let rest = url
        .strip_prefix("http://")
        .unwrap_or_else(|| url.strip_prefix("https://").unwrap_or(url));
    let (authority, path) = match rest.split_once('/') {
        Some((a, p)) => (a, format!("/{p}")),
        None => (rest, "/v1/systemone".to_string()),
    };
    let (host, port) = match authority.rsplit_once(':') {
        Some((h, p)) => (h.to_string(), p.parse().unwrap_or(8700)),
        None => (authority.to_string(), 80),
    };
    Self {
        host,
        port,
        path: if path == "/" { "/v1/systemone".into() } else { path },
        timeout: Duration::from_secs(120),
    }
}

/// One decision round: build the wire body from `req`, POST it, map
/// the answers back. Returns the response plus the usage record.
pub fn decide(&self, req: &DecisionRequest) -> Result<(DecisionResponse, ClmUsage), ClmError> {
    let body = build_body(req).to_string();
    let t0 = Instant::now();
    let (status, headers, body) = self.post(body.as_bytes())?;
    let client_ms = t0.elapsed().as_secs_f64() * 1000.0;
    if status != 200 {
        return err(format!(
            "POST {} -> HTTP {status}: {}",
            self.path,
            String::from_utf8_lossy(&body)
        ));
    }
    let server_ms = headers
        .get("x-clm-latency-ms")
        .and_then(|v| v.trim().parse::<f64>().ok());
    let parsed: Value = serde_json::from_slice(&body)
        .map_err(|e| ClmError(format!("response is not JSON: {e}")))?;
    let input_tokens = parsed
        .pointer("/usage/input_tokens")
        .and_then(Value::as_u64)
        .ok_or_else(|| ClmError("response missing usage.input_tokens".into()))?;
    Ok((
        map_response(req, &parsed)?,
        ClmUsage {
            input_tokens,
            client_ms,
            server_ms,
        },
    ))
}

/// The hand-rolled HTTP/1.1 POST (`Connection: close`), mirroring
/// `serve.rs`'s min-envelope posture from the client side.
fn post(&self, body: &[u8]) -> Result<HttpReply, ClmError> {
    let mut stream = TcpStream::connect((self.host.as_str(), self.port))
        .map_err(|e| ClmError(format!("connect {}:{}: {e}", self.host, self.port)))?;
    stream
        .set_read_timeout(Some(self.timeout))
        .and_then(|_| stream.set_write_timeout(Some(self.timeout)))
        .map_err(|e| ClmError(format!("set timeout: {e}")))?;
    let head = format!(
        "POST {} HTTP/1.1\r\nHost: {}:{}\r\nContent-Type: application/json\r\n\
         Content-Length: {}\r\nConnection: close\r\n\r\n",
        self.path,
        self.host,
        self.port,
        body.len()
    );
    stream
        .write_all(head.as_bytes())
        .and_then(|_| stream.write_all(body))
        .and_then(|_| stream.flush())
        .map_err(|e| ClmError(format!("write: {e}")))?;
    let mut raw = Vec::new();
    stream
        .read_to_end(&mut raw)
        .map_err(|e| ClmError(format!("read: {e}")))?;
    parse_http_response(&raw)

