pub fn leak_counts<S: AsRef<str>, L: PartialEq>(
    reference: &[(S, L)],
    query: &[(S, L)],
    params: LeakParams,
) -> Option<LeakCounts> {
    if reference.is_empty() || query.is_empty() {
        return None;
    }
    let texts: Vec<&str> = reference.iter().map(|(t, _)| t.as_ref()).collect();
    let index = ShingleIndex::build(&texts, params);
    let mut scratch = QueryScratch::for_index(&index);
    let cap = params.near_cap.unwrap_or(usize::MAX);
    let mut c = LeakCounts {
        reference: reference.len(),
        query: query.len(),
        ..LeakCounts::default()
    };
    for (i, (text, label)) in query.iter().enumerate() {
        if let Some(row) = index.exact_row(text.as_ref(), &mut scratch) {
            c.exact += 1;
            c.exact_label_conflict += usize::from(reference[row as usize].1 != *label);
            continue;
        }
        if i >= cap {
            continue;
        }
        c.near_scanned += 1;
        if let LeakClass::Near { row, .. } = index.classify_near(&mut scratch) {
            c.near += 1;
            c.near_same_label += usize::from(reference[row as usize].1 == *label);
        }
    }
    Some(c)
}

pub fn scan_eval<S: AsRef<str>, Q: AsRef<str>>(
    reference: &[S],
    query: &[Q],
    params: LeakParams,
) -> Option<EvalScan> {
    if reference.is_empty() || query.is_empty() {
        return None;
    }
    let texts: Vec<&str> = reference.iter().map(|t| t.as_ref()).collect();
    let index = ShingleIndex::build(&texts, params);
    let mut scratch = QueryScratch::for_index(&index);
    let cap = params.near_cap.unwrap_or(usize::MAX);
    let mut out = EvalScan {
        exact: 0,
        near: 0,
        near_scanned: 0,
        n_reference: reference.len(),
        n_eval: query.len(),
        flags: Vec::with_capacity(query.len()),
    };
    for (i, q) in query.iter().enumerate() {
        if index.exact_row(q.as_ref(), &mut scratch).is_some() {
            out.exact += 1;
            out.flags.push(true);
            continue;
        }
        if i >= cap {
            // Beyond the NEAR window: unscanned, NOT clean — kept in the
            // de-leaked set (conservative), never counted as a leak.
            out.flags.push(false);
            continue;
        }
        out.near_scanned += 1;
        if let LeakClass::Near { .. } = index.classify_near(&mut scratch) {
            out.near += 1;
            out.flags.push(true);
        } else {
            out.flags.push(false);
        }
    }
    Some(out)
}

